ex.org/W4411932316", "doi": "https://doi.org/10.1016/j.matt.2025.102263", "title": "El Agente: An autonomous agent for quantum chemistry", "publication_year": 2025, "type": "article", "cited_by_count": 71, "open_access": {"is_oa": true, "oa_status": "hybrid", "oa_url": "https://www.cell.com/matter/pdf/S2590-2385(25)00306-6.pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1016/j.matt.2025.102263", "doi": "https://doi.org/10.1016/j.matt.2025.102263", "is_oa": true, "landing_page_url": "https://doi.org/10.1016/j.matt.2025.102263", "pdf_url": "https://www.cell.com/matter/pdf/S2590-2385(25)00306-6.pdf", "source": {"id": "https://openalex.org/S4210178557", "display_name": "Matter", "issn_l": "2590-2385", "issn": ["2590-2385", "2590-2393"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["cwts-core", "dongbi-b", "jufo-1", "ki-jl-1", "norway-1", "poland-20", "russia-white-list-1"], "host_organization": "https://openalex.org/P4310320990", "host_organization_name": "Elsevier BV", "host_organization_lineage": ["https://openalex.org/P4310320990"], "host_organization_lineage_names": ["Elsevier BV"], "type": "journal"}, "license": "cc-by-nc-sa", "license_id": "https://openalex.org/licenses/cc-by-nc-sa", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Matter", "raw_type": "journal-article"}, "abstract": "Computational chemistry tools are widely used to study the behaviour of chemical phenomena. Yet, the complexity of these tools can make them inaccessible to non-specialists and challenging even for experts. In this work, we introduce El Agente Q, an LLM-based multi-agent system that dynamically generates and executes quantum chemistry workflows from natural language user prompts. The system is built on a novel cognitive architecture featuring a hierarchical memory framework that enables flexible task decomposition, adaptive tool selection, post-analysis, and autonomous file handling and submission. El Agente Q is benchmarked on six university-level course exercises and two case studies, demonstrating robust problem-solving performance (averaging >87% task success) and adaptive error handling through in situ debugging. It also supports longer-term, multi-step task execution for more complex workflows, while maintaining transparency through detailed action trace logs. Together, these capabilities lay the foundation for increasingly autonomous and accessible quantum chemistry."}]", "excerpt_truncated": true, "source_sha256": "429b12f23c36b3e4817f38d8f3346af2da4b94a12c9ba429804d003d832b1ba3", "verification_required": true, "topic_domain": "creator_objective_critique", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s11704-024-40231-1", "doi:10.1007/s11704-024-40231-1.pdf", "doi:10.1016/j.matt.2025.102263", "openalex:W4393065402"], "source_candidates": ["https://doi.org/10.1007/s11704-024-40231-1", "https://link.springer.com/content/pdf/10.1007/s11704-024-40231-1.pdf", "https://doi.org/10.1016/j.matt.2025.102263", "https://www.cell.com/matter/pdf/S2590-2385(25)00306-6.pdf"], "source_candidate_identities": {}}
